effect.shader:
void main() {
    vec2 uv = acScreenNorm;
    vec4 src = texture2DCv(inputImg.texture, uv);
    
    // 1. Calculate Luminance (standard weights for grayscale)
    float lum = dot(src.rgb, vec3(0.299, 0.587, 0.114));
    
    // 2. Map colors based on luminance
    vec3 tritoneCol;
    if (lum < 0.5) {
        // Map Shadows to Midtones
        tritoneCol = mix(shadows.rgb, midtones.rgb, lum * 2.0);
    } else {
        // Map Midtones to Highlights
        tritoneCol = mix(midtones.rgb, highlights.rgb, (lum - 0.5) * 2.0);
    }
    
    // 3. Blend with original
    vec3 finalCol = mix(tritoneCol, src.rgb, blend);
    
    // 4. Output with original alpha
    gl_FragColor = vec4(finalCol, 1.0) * src.a;
}
